			assertEpsilonEquals(0, getS().getMinZ());
			assertEpsilonEquals(123.456, getS().getMaxX());
			assertEpsilonEquals(456.789, getS().getMaxY());
			assertEpsilonEquals(10, getS().getMaxZ());
